// Fisko-KlangFinance, round R6: vehicles, meeting rooms, buildings and building equipment, repair requests and routine
// inspections. Written new for the DPT finance division, from the duty list (supplies group: vehicle work and premises
// work) and the meeting (MoM 2 Nov 2569: how long building equipment lasts, facility management, cars and where they
// park, building budget, safety, queues for cars and meeting rooms).
// Sample thresholds, not rules: the 30-day warning before a registration or insurance expires, the 90% of useful life
// warning, the 14-day open repair warning. Nothing here is connected to the Department of Land Transport, insurers, fuel
// cards or building sensors; every figure is typed. Useful lives are sample values to confirm against the regulations.
// Not done: security, cleaning and guard contracts, utility meters and bills, phones, the water-treatment and waste
// records as readings (only a routine-inspection checklist), mobile or map display of car positions, driver licences.
const FC_ACT = ["proc", "prochead"]; // who manages the registers and decides bookings; sample assumption, to confirm
const fcActor = () => FC_ACT.includes(ROLE);
const FC_WARN_DAYS = 30, FC_LIFE_WARN = 0.9, FC_WO_DAYS = 14;
const fcDays = (a, b) => Math.round((new Date(b) - new Date(a)) / 864e5);
const fcMine = u => !(ROLE === "div" || ROLE === "divhead") || u === me().unit;
const fcOverlap = (a, b) => a.start < b.end && a.end > b.start;
const fcTime = s => String(s || "").replace("T", " ");

