const eqAge = e => Math.max(0, (new Date(TODAY).getFullYear() - new Date(e.inst).getFullYear()) * 12 + new Date(TODAY).getMonth() - new Date(e.inst).getMonth()), eqUsed = e => eqAge(e) / (e.life * 12), eqNext = e => { const d = new Date(e.svcLast); d.setDate(d.getDate() + e.svcEvery); return d.toISOString().slice(0, 10); };
