function fcAlerts() {
  const out = [], add = (sev, th, en, link, due) => out.push({ sev, title: L(th, en), link, due: due || TODAY });
  (S.vehicles || []).filter(v => v.status !== "retired").forEach(v => [["regExp", "ทะเบียน/ภาษี", "registration"], ["insExp", "ประกันภัย", "insurance"]].forEach(([k, th, en]) => { const d = vhDue(v[k]); if (d == null) return; if (d < 0) add("high", `${v.plate} ${th}หมดอายุแล้ว ${fdate(v[k])}`, `${v.plate} ${en} expired ${fdate(v[k])}`, "vh-reg", v[k]); else if (d <= FC_WARN_DAYS) add("mid", `${v.plate} ${th}จะหมดอายุ ${fdate(v[k])}`, `${v.plate} ${en} expires ${fdate(v[k])}`, "vh-reg", v[k]); }));
  (S.bequip || []).filter(e => e.status !== "retired").forEach(e => { const s = eqState(e); if (s === "svc") add("high", `${e.name} (${blName(e.bldg)}) เลยกำหนดบำรุงรักษา ${fdate(eqNext(e))}`, `${e.name} (${blName(e.bldg)}) service overdue ${fdate(eqNext(e))}`, "fm-eq", eqNext(e)); else if (s === "end") add("high", `${e.name} (${blName(e.bldg)}) เกินอายุใช้งาน`, `${e.name} (${blName(e.bldg)}) is past its useful life`, "fm-eq"); else if (s === "near") add("mid", `${e.name} (${blName(e.bldg)}) ใช้ไปแล้ว ${Math.round(eqUsed(e) * 100)}% ของอายุใช้งาน`, `${e.name} (${blName(e.bldg)}) at ${Math.round(eqUsed(e) * 100)}% of life`, "fm-eq"); });
  (S.insps || []).forEach(x => { const s = inState(x); if (s === "over") add("high", `ตรวจ${tx(IN_KIND[x.kind])} (${blName(x.bldg)}) เลยกำหนด ${fdate(inNext(x))}`, `${tx(IN_KIND[x.kind])} inspection (${blName(x.bldg)}) overdue ${fdate(inNext(x))}`, "fm-insp", inNext(x)); else if (s === "soon") add("mid", `ตรวจ${tx(IN_KIND[x.kind])} (${blName(x.bldg)}) ถึงกำหนด ${fdate(inNext(x))}`, `${tx(IN_KIND[x.kind])} inspection (${blName(x.bldg)}) due ${fdate(inNext(x))}`, "fm-insp", inNext(x)); });
  (S.wos || []).filter(w => ["open", "assigned"].includes(w.status) && fcDays(w.t.slice(0, 10), TODAY) > FC_WO_DAYS).forEach(w => add("mid", `งานซ่อม ${w.id} ค้างเกิน ${FC_WO_DAYS} วัน: ${w.what}`, `Repair ${w.id} open over ${FC_WO_DAYS} days: ${w.what}`, "fm-wo", w.t));
  (S.wos || []).filter(w => w.status === "open" && w.prio === "high").forEach(w => add("high", `แจ้งซ่อมเร่งด่วน ${w.id} ยังไม่มีผู้รับเรื่อง: ${w.what}`, `Urgent repair ${w.id} not taken on: ${w.what}`, "fm-wo", w.t));
  (S.bldgs || []).forEach(b => { if (blSpend(b.id) > b.budget) add("high", `${b.name} ใช้งบบริหารอาคารเกินงบ`, `${b.name} is over its building budget`, "fm-bldg"); else if (b.budget && blSpend(b.id) / b.budget >= 0.9) add("mid", `${b.name} ใช้งบบริหารอาคารไปแล้วเกินร้อยละ 90`, `${b.name} has used over 90% of its building budget`, "fm-bldg"); });
  const rank = { high: 0, mid: 1 }; return out.sort((a, b) => rank[a.sev] - rank[b.sev] || String(a.due).localeCompare(String(b.due)));
}
