fcPage("vh-fuel", "VH3", "vhg", "สถิติการใช้เชื้อเพลิง", "Fuel use", "เชื้อเพลิงที่บันทึกตอนคืนรถในจัดคิวรถเข้ามาที่นี่อัตโนมัติ เติมนอกการจองบันทึกเองได้ · สรุปลิตร ค่าใช้จ่าย ระยะทาง และอัตราสิ้นเปลือง (กม./ลิตร) จากเลขไมล์ · กันเลขไมล์ถอยหลัง · ไม่ได้เชื่อมบัตรเติมน้ำมัน", "Fuel per vehicle with litres, cost, distance and km per litre from the odometer · odometer cannot go backwards · no fuel-card link", "fuel", () => (S.vehicles || []).filter(v => v.kind !== "machine").slice(0, 4).map(v => { const s = flStats(v.id); return [v.plate, s.kmpl ? s.kmpl.toFixed(1) + " " + L("กม./ลิตร", "km/L") : "–", `${fmt(s.litres, 0)} ${L("ลิตร", "L")} · ${fmt(s.cost)} ${L("บาท", "baht")}`]; }));
